import{_ as a}from"./chunks/none.BOvQNh81.js";import{_ as e}from"./chunks/taa.BVy4jANc.js";import{_ as s}from"./chunks/msaa.Csk7w4Rk.js";import{_ as i}from"./chunks/fxaa.DCmrqC5I.js";import{_ as l}from"./chunks/toneMappingControl.VZWC7SL8.js";import{f as n,o as d,c as o,a2 as r}from"./chunks/framework.n5RLHRfo.js";const E=JSON.parse('{"title":"Antialiasing","description":"","frontmatter":{"title":"Antialiasing","order":10},"headers":[],"relativePath":"ko/antialiasing/index.md","filePath":"ko/antialiasing/index.md","lastUpdated":1792993711000}'),g={name:"ko/antialiasing/index.md"};function c(h,t,p,A,m,f){return d(),o("div",null,[...t[0]||(t[0]=[r(`<h1 id="안티앨리어싱" tabindex="-1">안티앨리어싱 <a class="header-anchor" href="#안티앨리어싱" aria-label="Permalink to &quot;안티앨리어싱&quot;">​</a></h1><p><strong>안티앨리어싱</strong>(Antialiasing)은 3D 렌더링 시 발생하는 계단 현상 (Aliasing)을 제거하여 부드러운 외곽선과 화면을 만드는 기술입니다. RedGPU는 시간축 누적 기반의 <strong><a href="./taa.html"><code>TAA</code></a></strong>, 하드웨어 멀티샘플링 기반의 <strong><a href="./msaa.html"><code>MSAA</code></a></strong>, 후처리 필터 기반의 <strong><a href="./fxaa.html"><code>FXAA</code></a></strong> 를 제공하며, 모든 설정은 <a href="/RedGPU/manual/ko/api/RedGPU-API/namespaces/RedGPU/namespaces/Antialiasing/classes/AntialiasingManager.html"><code>redGPUContext.antialiasingManager</code></a>(<a href="/RedGPU/manual/ko/api/RedGPU-API/namespaces/RedGPU/namespaces/Antialiasing/classes/AntialiasingManager.html"><code>AntialiasingManager</code></a>)를 통해 통합 제어됩니다.</p><hr><h2 id="_1-기본-동작-및-활성화-규칙" tabindex="-1">1. 기본 동작 및 활성화 규칙 <a class="header-anchor" href="#_1-기본-동작-및-활성화-규칙" aria-label="Permalink to &quot;1. 기본 동작 및 활성화 규칙&quot;">​</a></h2><p>RedGPU의 안티앨리어싱 시스템은 <strong>배타적</strong>으로 동작합니다. 한 번에 하나의 기법만 활성화할 수 있으며, 새로운 기법을 켜면 기존 설정은 자동으로 해제됩니다.</p><h3 id="초기화-시-자동-선택-auto-selection" tabindex="-1">초기화 시 자동 선택 (Auto-Selection) <a class="header-anchor" href="#초기화-시-자동-선택-auto-selection" aria-label="Permalink to &quot;초기화 시 자동 선택 (Auto-Selection)&quot;">​</a></h3><p>엔진 초기화 시 디스플레이의 픽셀 밀도 (<code>window.devicePixelRatio</code>)를 감지하여 최적의 기법이 기본으로 활성화됩니다.</p><ul><li><strong>고해상도 디스플레이</strong> (<code>devicePixelRatio &gt; 1.0</code>): <strong><a href="/RedGPU/manual/ko/api/RedGPU-API/namespaces/RedGPU/namespaces/Antialiasing/classes/TAA.html"><code>TAA</code></a></strong> 기본 활성화 (<code>useTAA = true</code>)</li><li><strong>일반 디스플레이</strong> (<code>devicePixelRatio &lt;= 1.0</code>): <strong><code>MSAA</code></strong> 기본 활성화 (<code>useMSAA = true</code>)</li></ul><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">antialiasingManager</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> redGPUContext;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 안티앨리어싱 모드 전환 (기존 활성 모드는 자동 해제됨)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">antialiasingManager.useTAA </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><hr><h2 id="_2-기법별-비교" tabindex="-1">2. 기법별 비교 <a class="header-anchor" href="#_2-기법별-비교" aria-label="Permalink to &quot;2. 기법별 비교&quot;">​</a></h2><p>렌더링 품질과 성능 목표에 따라 적절한 기법을 선택할 수 있습니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">기법</th><th style="text-align:left;">방식</th><th style="text-align:left;">품질 및 특징</th><th style="text-align:left;">성능 비용</th><th style="text-align:left;">비교 이미지</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>NONE</strong></td><td style="text-align:left;">미적용</td><td style="text-align:left;">안티앨리어싱을 적용하지 않은 원본 상태 (계단 현상 발생)</td><td style="text-align:left;">없음</td><td style="text-align:left;"><img src="`+a+'" alt="None"></td></tr><tr><td style="text-align:left;"><strong><a href="./taa.html">TAA</a></strong></td><td style="text-align:left;">시간축 누적</td><td style="text-align:left;">지오메트리 외곽선과 셰이더/텍스처 내부 알리어싱까지 제거</td><td style="text-align:left;">중간</td><td style="text-align:left;"><img src="'+e+'" alt="TAA"></td></tr><tr><td style="text-align:left;"><strong><a href="./msaa.html">MSAA</a></strong></td><td style="text-align:left;">하드웨어 샘플링</td><td style="text-align:left;">지오메트리 외곽선만 선명하게 처리 (텍스처 내부 패턴 및 알파 컷오프 경계는 미적용)</td><td style="text-align:left;">높음</td><td style="text-align:left;"><img src="'+s+'" alt="MSAA"></td></tr><tr><td style="text-align:left;"><strong><a href="./fxaa.html">FXAA</a></strong></td><td style="text-align:left;">후처리 필터</td><td style="text-align:left;">최종 이미지의 경계를 빠르게 보정 (미세한 블러 동반)</td><td style="text-align:left;">매우 낮음</td><td style="text-align:left;"><img src="'+i+'" alt="FXAA"></td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>실시간 테스트 안내</strong>: RedGPU의 모든 예제 화면 UI에 위치한 <strong><code>ANTIALIASING</code></strong> 드롭다운 메뉴를 통해 현재 실행 중인 씬에서 <a href="/RedGPU/manual/ko/api/RedGPU-API/namespaces/RedGPU/namespaces/Antialiasing/classes/TAA.html"><code>TAA</code></a>, <code>MSAA</code>, <a href="/RedGPU/manual/ko/api/RedGPU-API/namespaces/RedGPU/namespaces/Antialiasing/classes/FXAA.html"><code>FXAA</code></a>, <code>NONE</code> 모드를 즉시 전환하며 비교해 볼 수 있습니다.</p><p><img src="'+l+'" alt="Antialiasing Control"></p></div><hr><p><a href="./taa.html">다음 단계: TAA 배우기</a></p>',16)])])}const R=n(g,[["render",c]]);export{E as __pageData,R as default};
